import json
import sys

def dedupe(rows):
    seen, output = set(), []
    for row in rows:
        key = row['id']
        if key in seen:
            continue
        seen.add(key)
        output.append(row)
    return output

if __name__ == '__main__':
    rows = [json.loads(line) for line in sys.stdin if line.strip()]
    for row in dedupe(rows):
        print(json.dumps(row, separators=(',', ':')))
